import React, { useEffect, useState } from 'react';
import { getUsers, createUser, updateUser, deleteUser } from '../api/user.api';

const ROLES = ['employee', 'driver', 'subadmin', 'admin'];

const parseCurrentUser = () => {
  try { return JSON.parse(localStorage.getItem('user')); }
  catch { return null; }
};

const UserManagement = () => {
  const currentUser = parseCurrentUser();
  const isAdmin = currentUser?.role === 'admin';

  const [users, setUsers] = useState([]);
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'employee' });
  const [editId, setEditId] = useState(null);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchUsers = async () => {
    try {
      const res = await getUsers();
      setUsers(res.data || []);
    } catch (err) {
      setError('Failed to load users.');
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (editId) {
        await updateUser(editId, { name: form.name, role: form.role, is_active: true });
      } else {
        await createUser(form);
      }
      setForm({ name: '', email: '', password: '', role: 'employee' });
      setEditId(null);
      fetchUsers();
    } catch (err) {
      setError(err.response?.data?.message || 'Operation failed.');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (user) => {
    setEditId(user.id);
    setForm({ name: user.name, email: user.email, password: '', role: user.role });
    setError('');
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this user?')) return;
    try {
      await deleteUser(id);
      fetchUsers();
    } catch (err) {
      setError('Delete failed.');
    }
  };

  const handleToggleActive = async (user) => {
    try {
      await updateUser(user.id, { name: user.name, role: user.role, is_active: !user.is_active });
      fetchUsers();
    } catch { setError('Update failed.'); }
  };

  const filtered = users.filter((u) => {
    const t = search.toLowerCase();
    return (
      u.name?.toLowerCase().includes(t) ||
      u.email?.toLowerCase().includes(t) ||
      u.role?.toLowerCase().includes(t) ||
      String(u.id).includes(t)
    );
  });

  return (
    <div>
      <div className="page-title">
        <div>
          <h2>User Management</h2>
          <p>Manage profiles, roles, and access for all users.</p>
        </div>
      </div>

      {error && <div className="error-message" style={{ marginBottom: 16 }}>{error}</div>}

      <div className="form-card">
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>{editId ? 'Edit User' : 'Create New User'}</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              {editId ? 'Update name and role.' : 'Add a new member to the system.'}
            </p>
          </div>
          <input
            className="filter-input"
            placeholder="Search users..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <form onSubmit={handleSubmit} className="form-grid">
          <div className="field-group">
            <label>Name</label>
            <input
              placeholder="Full Name"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              required
            />
          </div>
          <div className="field-group">
            <label>Email</label>
            <input
              type="email"
              placeholder="user@example.com"
              value={form.email}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
              required={!editId}
              disabled={!!editId}
            />
          </div>
          {!editId && (
            <div className="field-group">
              <label>Password</label>
              <input
                type="password"
                placeholder="Min 8 characters"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                required
                minLength={8}
              />
            </div>
          )}
          <div className="field-group">
            <label>Role</label>
            <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
              {ROLES.filter(r => isAdmin ? true : r !== 'admin').map(r => (
                <option key={r} value={r}>{r.charAt(0).toUpperCase() + r.slice(1)}</option>
              ))}
            </select>
          </div>
          <div className="table-actions">
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Saving...' : editId ? 'Update User' : 'Add User'}
            </button>
            {editId && (
              <button type="button" className="btn btn-secondary" onClick={() => {
                setEditId(null);
                setForm({ name: '', email: '', password: '', role: 'employee' });
                setError('');
              }}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>

      <div className="table-card" style={{ marginTop: 20 }}>
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>All Users</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              Showing {filtered.length} of {users.length} users
            </p>
          </div>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>Role</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr><td colSpan={6} style={{ textAlign: 'center', color: 'var(--muted)' }}>No users found</td></tr>
              ) : filtered.map((u) => (
                <tr key={u.id}>
                  <td>{u.id}</td>
                  <td>{u.name}</td>
                  <td>{u.email}</td>
                  <td>
                    <span className={`status-pill status-role-${u.role}`}>{u.role}</span>
                  </td>
                  <td>
                    <span
                      className={`status-pill ${u.is_active ? 'success' : 'danger'}`}
                      style={{ cursor: 'pointer' }}
                      onClick={() => handleToggleActive(u)}
                      title="Click to toggle"
                    >
                      {u.is_active ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td className="table-actions">
                    <button className="btn btn-secondary" onClick={() => handleEdit(u)}>Edit</button>
                    {isAdmin && (
                      <button className="btn btn-danger" onClick={() => handleDelete(u.id)}>Delete</button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default UserManagement;
